<template>
  <div class="quality-page">
    <header class="quality-hero"><div><small>WATER QUALITY LOG</small><h1>水质日志</h1><p>持续记录同一水体的客观测量值，比单次数据更容易发现变化。</p></div><div class="hero-actions"><el-button @click="showTargetEditor = !showTargetEditor">{{ showTargetEditor ? '收起参考范围' : '设置参考范围' }}</el-button><el-button :disabled="!selectedPond" :loading="exporting === 'pond'" @click="exportCsv(selectedPond)">导出{{ selectedPond || '当前水体' }} CSV</el-button><el-button :disabled="total === 0" :loading="exporting === 'all'" @click="exportCsv()">导出全部</el-button></div></header>
    <el-alert type="info" :closable="false" show-icon title="数据仅用于连续观察"><template #default>不同品种、阶段和养殖模式的适宜范围不同。本页不自动判定是否安全；异常数据请复测并结合专业意见处理。</template></el-alert>

    <section v-if="pondOverview.length" class="pond-overview" aria-label="水体状态总览">
      <div class="overview-head"><div><small>POND OVERVIEW</small><h2>水体状态总览</h2><p>基于每个水体的最新读数和你设置的个人参考范围。</p></div><span>{{ pondOverview.length }} 个水体</span></div>
      <div class="overview-grid">
        <article v-for="pond in pondOverview" :key="pond.pondName" :class="{ attention: pond.deviations.length, active: selectedPond === pond.pondName }">
          <button class="overview-main" type="button" :aria-label="`查看${pond.pondName}水质趋势`" @click="selectPond(pond.pondName)">
            <span class="overview-title"><strong>{{ pond.pondName }}</strong><span class="overview-badges"><em v-if="pond.deviations.length">{{ pond.deviations.length }} 项偏离</em><em v-if="pond.stale" class="stale">{{ pond.ageDays }} 天未测</em><em v-if="!pond.deviations.length && !pond.stale && pond.hasTarget" class="normal">最新值在个人范围内</em><em v-if="!pond.hasTarget" class="unset">未设置参考范围</em></span></span>
            <span class="overview-metrics">{{ latestSummary(pond.latest) }}</span>
            <small>{{ formatDate(pond.latest.observedAt) }} · 查看趋势 →</small>
          </button>
          <div v-if="pond.deviations.length || pond.stale" class="overview-actions"><button v-if="pond.stale" class="test-shortcut" type="button" :aria-label="`为${pond.pondName}安排水质检测`" @click="scheduleWaterTest(pond)">安排检测</button><button v-if="pond.deviations.length" class="diagnose-shortcut" type="button" :aria-label="`将${pond.pondName}异常水质带入诊断`" @click="startDiagnosis(pond)">带入 AI 诊断 →</button></div>
        </article>
      </div>
    </section>

    <section v-if="showTargetEditor" class="target-card">
      <div class="target-head"><div><small>PERSONAL REFERENCE</small><h2>个人参考范围</h2><p>数值由你自行确定，仅用于突出偏离项，不代表通用安全标准。</p></div><span v-if="targetForm.id">正在编辑：{{ targetForm.pondName }}</span></div>
      <form class="target-form" @submit.prevent="saveTarget">
        <label><span>水体名称 *</span><input v-model.trim="targetForm.pondName" required maxlength="64" list="pond-options" placeholder="选择或输入水体" /><datalist id="pond-options"><option v-for="pond in ponds" :key="pond" :value="pond" /></datalist></label>
        <label><span>最低水温 °C</span><input v-model.number="targetForm.temperatureMin" type="number" min="-5" max="50" step="0.1" /></label>
        <label><span>最高水温 °C</span><input v-model.number="targetForm.temperatureMax" type="number" min="-5" max="50" step="0.1" /></label>
        <label><span>最低 pH</span><input v-model.number="targetForm.phMin" type="number" min="0" max="14" step="0.01" /></label>
        <label><span>最高 pH</span><input v-model.number="targetForm.phMax" type="number" min="0" max="14" step="0.01" /></label>
        <label><span>最低溶氧 mg/L</span><input v-model.number="targetForm.dissolvedOxygenMin" type="number" min="0" max="50" step="0.01" /></label>
        <label><span>最高氨氮 mg/L</span><input v-model.number="targetForm.ammoniaMax" type="number" min="0" max="1000" step="0.001" /></label>
        <label><span>最高亚硝酸盐 mg/L</span><input v-model.number="targetForm.nitriteMax" type="number" min="0" max="1000" step="0.001" /></label>
        <div class="target-actions"><el-button native-type="button" @click="targetForm = emptyTargetForm()">清空</el-button><el-button type="primary" native-type="submit" :loading="targetSaving">保存个人范围</el-button></div>
      </form>
      <div v-if="targets.length" class="saved-targets"><article v-for="target in targets" :key="target.id"><div><strong>{{ target.pondName }}</strong><span>{{ targetDescription(target) }}</span></div><div><el-button text @click="editTarget(target)">编辑</el-button><el-button text type="danger" @click="removeTarget(target)">删除</el-button></div></article></div>
    </section>

    <section class="trend-card">
      <div class="trend-head">
        <div><small>TREND VIEW</small><h2>变化趋势</h2><p>选择同一水体和指标，观察一段时间内的方向与波动。</p></div>
        <div class="trend-filters">
          <label><span>水体</span><select v-model="selectedPond" :disabled="!ponds.length" @change="loadTrend"><option v-if="!ponds.length" value="">暂无记录</option><option v-for="pond in ponds" :key="pond" :value="pond">{{ pond }}</option></select></label>
          <label><span>范围</span><select v-model.number="trendDays" @change="loadTrend"><option :value="30">近 30 天</option><option :value="90">近 90 天</option><option :value="365">近一年</option></select></label>
        </div>
      </div>
      <div class="metric-tabs" aria-label="选择趋势指标">
        <button v-for="metric in metrics" :key="metric.key" type="button" :class="{ active: activeMetric === metric.key }" @click="activeMetric = metric.key">{{ metric.label }}</button>
      </div>
      <div v-loading="trendLoading" class="trend-body">
        <p v-if="activeTargetDescription" class="active-reference">当前个人参考：{{ activeTargetDescription }}</p>
        <template v-if="chartPoints.length >= 2">
          <div class="trend-summary"><div><span>最新读数</span><strong>{{ latestValue }} <small>{{ activeMetricInfo.unit }}</small></strong></div><div><span>较上次</span><strong :class="deltaClass">{{ deltaText }}</strong></div><div><span>有效测量</span><strong>{{ chartPoints.length }} <small>次</small></strong></div></div>
          <div class="chart-wrap">
            <svg viewBox="0 0 640 190" role="img" :aria-label="`${selectedPond}${activeMetricInfo.label}变化折线图`">
              <line v-for="y in [25,70,115,160]" :key="y" x1="36" :y1="y" x2="620" :y2="y" class="grid-line" />
              <polyline :points="polylinePoints" class="trend-line" />
              <circle v-for="point in chartPoints" :key="`${point.x}-${point.y}`" :cx="point.x" :cy="point.y" r="4" class="trend-point"><title>{{ point.label }}：{{ point.value }} {{ activeMetricInfo.unit }}</title></circle>
            </svg>
            <div class="chart-axis"><span>{{ firstTrendDate }}</span><span>{{ lastTrendDate }}</span></div>
          </div>
        </template>
        <div v-else class="trend-empty">{{ selectedPond ? `当前范围内至少需要 2 次${activeMetricInfo.label}测量才能形成趋势` : '保存水质记录后可查看趋势' }}</div>
      </div>
    </section>

    <div class="quality-grid">
      <section ref="formSection" class="quality-form-card" :class="{ editing: editingId != null }">
        <div class="form-title"><div><h2>{{ editingId != null ? '编辑测量' : copiedFrom ? '新增复测' : '新增测量' }}</h2><p>{{ editingId != null ? `正在修改记录 #${editingId}` : copiedFrom ? `已复制 ${copiedFrom} 的读数，请核对并修改本次测量值。` : '至少填写一项指标。单位请与仪器读数核对。' }}</p></div><el-tag v-if="editingId != null" type="warning">编辑模式</el-tag><el-tag v-else-if="copiedFrom" type="success">复测草稿</el-tag></div>
        <div v-if="linkedTaskId" class="linked-task-notice"><b>正在记录待办结果</b><span>{{ linkedTaskTitle || `待办 #${linkedTaskId}` }} · 保存读数后将自动完成该待办。</span></div>
        <form @submit.prevent="save">
          <label class="wide"><span>水体名称 *</span><input v-model.trim="form.pondName" required maxlength="64" placeholder="例如：一号池、客厅鱼缸" /></label>
          <label class="wide"><span>测量时间 *</span><input v-model="form.observedAt" required type="datetime-local" /></label>
          <label><span>水温（°C）</span><input v-model.number="form.temperature" type="number" min="-5" max="50" step="0.1" inputmode="decimal" /></label>
          <label><span>pH</span><input v-model.number="form.ph" type="number" min="0" max="14" step="0.01" inputmode="decimal" /></label>
          <label><span>溶氧（mg/L）</span><input v-model.number="form.dissolvedOxygen" type="number" min="0" max="50" step="0.01" inputmode="decimal" /></label>
          <label><span>氨氮（mg/L）</span><input v-model.number="form.ammonia" type="number" min="0" max="1000" step="0.001" inputmode="decimal" /></label>
          <label><span>亚硝酸盐（mg/L）</span><input v-model.number="form.nitrite" type="number" min="0" max="1000" step="0.001" inputmode="decimal" /></label>
          <label class="wide"><span>备注</span><textarea v-model.trim="form.notes" maxlength="500" rows="3" placeholder="如：换水前、增氧后、雨后复测"></textarea></label>
          <div class="wide form-actions"><el-button native-type="button" @click="resetForm">{{ editingId != null ? '取消编辑' : '清空' }}</el-button><el-button type="primary" native-type="submit" :loading="saving">{{ editingId != null ? '保存修改' : '保存水质记录' }}</el-button></div>
        </form>
      </section>

      <section class="quality-records" v-loading="loading">
        <div class="records-head"><div><h2>最近记录</h2><p>按测量时间倒序展示，每页 20 条。</p></div><el-button :icon="Refresh" circle aria-label="刷新水质记录" @click="load" /></div>
        <article v-for="item in records" :key="item.id" class="quality-record">
          <div class="record-title"><div><strong>{{ item.pondName }}</strong><span>{{ formatDate(item.observedAt) }}</span></div><div class="record-actions"><el-button text aria-label="基于此记录复测" @click="startRetest(item)">复测</el-button><el-button v-if="deviationLabels(item).length" text type="primary" aria-label="为异常水质生成复测待办" @click="createRetestTask(item)">生成复测待办</el-button><el-button text aria-label="编辑水质记录" @click="startEdit(item)">编辑</el-button><el-button text type="danger" aria-label="删除水质记录" @click="remove(item)">删除</el-button></div></div>
          <div class="metrics">
            <div v-if="item.temperature != null" :class="{ attention: outOfRange(item, 'temperature') }"><small>水温</small><b>{{ item.temperature }}<i>°C</i></b><em v-if="outOfRange(item, 'temperature')">偏离个人范围</em></div>
            <div v-if="item.ph != null" :class="{ attention: outOfRange(item, 'ph') }"><small>pH</small><b>{{ item.ph }}</b><em v-if="outOfRange(item, 'ph')">偏离个人范围</em></div>
            <div v-if="item.dissolvedOxygen != null" :class="{ attention: outOfRange(item, 'dissolvedOxygen') }"><small>溶氧</small><b>{{ item.dissolvedOxygen }}<i>mg/L</i></b><em v-if="outOfRange(item, 'dissolvedOxygen')">低于个人范围</em></div>
            <div v-if="item.ammonia != null" :class="{ attention: outOfRange(item, 'ammonia') }"><small>氨氮</small><b>{{ item.ammonia }}<i>mg/L</i></b><em v-if="outOfRange(item, 'ammonia')">高于个人范围</em></div>
            <div v-if="item.nitrite != null" :class="{ attention: outOfRange(item, 'nitrite') }"><small>亚硝酸盐</small><b>{{ item.nitrite }}<i>mg/L</i></b><em v-if="outOfRange(item, 'nitrite')">高于个人范围</em></div>
          </div>
          <p v-if="item.notes">{{ item.notes }}</p>
        </article>
        <el-empty v-if="!loading && !records.length" description="还没有水质记录" />
        <el-pagination v-if="total > 20" v-model:current-page="page" class="quality-pagination" layout="prev, pager, next" :page-size="20" :total="total" @current-change="load" />
      </section>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
import { axiosInstance, http } from '@/utils/http'
const route=useRoute(),router=useRouter()

type RecordItem = { id:number; pondName:string; temperature?:number|null; ph?:number|null; dissolvedOxygen?:number|null; ammonia?:number|null; nitrite?:number|null; notes?:string; observedAt:string; createdAt:string }
type TargetItem = { id:number; pondName:string; temperatureMin?:number|null; temperatureMax?:number|null; phMin?:number|null; phMax?:number|null; dissolvedOxygenMin?:number|null; ammoniaMax?:number|null; nitriteMax?:number|null; updatedAt:string }
type PondOverview = { pondName:string; latest:RecordItem; hasTarget:boolean; deviations:string[]; ageDays:number; stale:boolean }
type MetricKey = 'temperature'|'ph'|'dissolvedOxygen'|'ammonia'|'nitrite'
const metrics:{key:MetricKey;label:string;unit:string}[]=[{key:'temperature',label:'水温',unit:'°C'},{key:'ph',label:'pH',unit:''},{key:'dissolvedOxygen',label:'溶氧',unit:'mg/L'},{key:'ammonia',label:'氨氮',unit:'mg/L'},{key:'nitrite',label:'亚硝酸盐',unit:'mg/L'}]
function localNow() { const date=new Date(Date.now()-new Date().getTimezoneOffset()*60000); return date.toISOString().slice(0,16) }
function emptyForm() { return { pondName:'', temperature:undefined as number|undefined, ph:undefined as number|undefined, dissolvedOxygen:undefined as number|undefined, ammonia:undefined as number|undefined, nitrite:undefined as number|undefined, notes:'', observedAt:localNow() } }
function emptyTargetForm(){return{id:undefined as number|undefined,pondName:'',temperatureMin:undefined as number|undefined,temperatureMax:undefined as number|undefined,phMin:undefined as number|undefined,phMax:undefined as number|undefined,dissolvedOxygenMin:undefined as number|undefined,ammoniaMax:undefined as number|undefined,nitriteMax:undefined as number|undefined}}
const form=ref(emptyForm()),records=ref<RecordItem[]>([]),loading=ref(false),saving=ref(false),page=ref(1),total=ref(0)
const exporting=ref<'pond'|'all'|''>('')
const editingId=ref<number|null>(null),copiedFrom=ref(''),formSection=ref<HTMLElement|null>(null)
const linkedTaskId=ref<number|null>(null),linkedTaskTitle=ref('')
const ponds=ref<string[]>([]),selectedPond=ref(''),trendDays=ref(30),trendRecords=ref<RecordItem[]>([]),trendLoading=ref(false),activeMetric=ref<MetricKey>('ph')
const targets=ref<TargetItem[]>([]),targetForm=ref(emptyTargetForm()),showTargetEditor=ref(false),targetSaving=ref(false)
const pondOverview=ref<PondOverview[]>([])
async function load(){loading.value=true;try{const data=await http.get<any>('/api/water-quality',{page:page.value-1});records.value=data.content||[];total.value=data.totalElements||0}finally{loading.value=false}}
async function loadPonds(){ponds.value=await http.get<string[]>('/api/water-quality/ponds');if(!selectedPond.value||!ponds.value.includes(selectedPond.value))selectedPond.value=ponds.value[0]||'';await loadTrend()}
async function loadTrend(){if(!selectedPond.value){trendRecords.value=[];return}trendLoading.value=true;try{trendRecords.value=await http.get<RecordItem[]>('/api/water-quality/trend',{pondName:selectedPond.value,days:trendDays.value})}finally{trendLoading.value=false}}
async function loadTargets(){targets.value=await http.get<TargetItem[]>('/api/water-quality/targets')}
async function loadOverview(){pondOverview.value=await http.get<PondOverview[]>('/api/water-quality/overview')}
async function saveTarget(){const values=[targetForm.value.temperatureMin,targetForm.value.temperatureMax,targetForm.value.phMin,targetForm.value.phMax,targetForm.value.dissolvedOxygenMin,targetForm.value.ammoniaMax,targetForm.value.nitriteMax];if(!values.some((value:unknown)=>value!==undefined&&value!==null&&value!=='')){ElMessage.warning('请至少填写一项参考范围');return}targetSaving.value=true;try{const {id,...payload}=targetForm.value;await http.post('/api/water-quality/targets',payload);ElMessage.success('个人参考范围已保存');targetForm.value=emptyTargetForm();await Promise.all([loadTargets(),loadOverview()])}finally{targetSaving.value=false}}
function editTarget(target:TargetItem){targetForm.value={id:target.id,pondName:target.pondName,temperatureMin:target.temperatureMin??undefined,temperatureMax:target.temperatureMax??undefined,phMin:target.phMin??undefined,phMax:target.phMax??undefined,dissolvedOxygenMin:target.dissolvedOxygenMin??undefined,ammoniaMax:target.ammoniaMax??undefined,nitriteMax:target.nitriteMax??undefined}}
async function removeTarget(target:TargetItem){await ElMessageBox.confirm(`删除“${target.pondName}”的个人参考范围吗？`,'删除参考范围',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await http.delete(`/api/water-quality/targets/${target.id}`);ElMessage.success('个人参考范围已删除');if(targetForm.value.id===target.id)targetForm.value=emptyTargetForm();await Promise.all([loadTargets(),loadOverview()])}
async function save(){const has=[form.value.temperature,form.value.ph,form.value.dissolvedOxygen,form.value.ammonia,form.value.nitrite].some((value:unknown)=>value!==undefined&&value!==null&&value!=='');if(!has){ElMessage.warning('请至少填写一项测量值');return}saving.value=true;try{const payload={...form.value,observedAt:new Date(form.value.observedAt).toISOString()};const taskId=editingId.value==null?linkedTaskId.value:null;if(editingId.value!=null)await http.put(`/api/water-quality/${editingId.value}`,payload);else await http.post('/api/water-quality',payload);let taskCompleted=false;if(taskId){try{await http.patch(`/api/tasks/${taskId}/completion`,{completed:true});taskCompleted=true}catch{ElMessage.warning('水质记录已保存，但待办未能自动完成，请返回待办确认')}}ElMessage.success(editingId.value!=null?'水质记录已更新':taskCompleted?'水质记录已保存，关联待办已完成':'水质记录已保存');linkedTaskId.value=null;linkedTaskTitle.value='';if(route.query.taskId)await router.replace({path:'/fish/water-quality',query:payload.pondName?{pond:payload.pondName}:{}});resetForm();page.value=1;await Promise.all([load(),loadPonds(),loadOverview()])}finally{saving.value=false}}
function localInput(value:string){const date=new Date(value);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
async function startEdit(item:RecordItem){editingId.value=item.id;copiedFrom.value='';form.value={pondName:item.pondName,temperature:item.temperature??undefined,ph:item.ph??undefined,dissolvedOxygen:item.dissolvedOxygen??undefined,ammonia:item.ammonia??undefined,nitrite:item.nitrite??undefined,notes:item.notes||'',observedAt:localInput(item.observedAt)};await nextTick();formSection.value?.scrollIntoView({behavior:'smooth',block:'start'})}
async function startRetest(item:RecordItem){editingId.value=null;copiedFrom.value=`${item.pondName} · ${formatDate(item.observedAt)}`;form.value={pondName:item.pondName,temperature:item.temperature??undefined,ph:item.ph??undefined,dissolvedOxygen:item.dissolvedOxygen??undefined,ammonia:item.ammonia??undefined,nitrite:item.nitrite??undefined,notes:'',observedAt:localNow()};await nextTick();formSection.value?.scrollIntoView({behavior:'smooth',block:'start'});ElMessage.success('已复制上次读数，请填写本次实测值')}
function resetForm(){editingId.value=null;copiedFrom.value='';form.value=emptyForm()}
async function remove(item:RecordItem){await ElMessageBox.confirm('确定删除这条水质记录吗？','删除记录',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await http.delete(`/api/water-quality/${item.id}`);if(editingId.value===item.id)resetForm();ElMessage.success('记录已删除');await Promise.all([load(),loadPonds(),loadOverview()])}
function formatDate(value:string){return new Date(value).toLocaleString()}
async function exportCsv(pondName?:string){const scope=pondName?'pond':'all';exporting.value=scope;try{const blob=await axiosInstance.get<any,Blob>('/api/water-quality/export',{params:pondName?{pondName}:undefined,responseType:'blob'});const url=URL.createObjectURL(blob);const a=document.createElement('a');const safePond=pondName?.replace(/[\\/:*?"<>|]/g,'-');a.href=url;a.download=`水质日志${safePond?`-${safePond}`:''}-${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);ElMessage.success(pondName?`已导出“${pondName}”的水质记录`:`已导出全部 ${total.value} 条水质记录`)}finally{exporting.value=''}}
const activeMetricInfo=computed(()=>metrics.find(metric=>metric.key===activeMetric.value)!)
const metricValues=computed(()=>trendRecords.value.map(item=>({value:item[activeMetric.value],observedAt:item.observedAt})).filter((item):item is {value:number;observedAt:string}=>typeof item.value==='number'))
const chartPoints=computed(()=>{const values=metricValues.value;if(!values.length)return[];const raw=values.map(item=>item.value),min=Math.min(...raw),max=Math.max(...raw),padding=max===min?1:(max-min)*.12,low=min-padding,high=max+padding;return values.map((item,index)=>({x:36+(values.length===1?0:index/(values.length-1))*584,y:160-((item.value-low)/(high-low))*135,value:item.value,label:formatDate(item.observedAt)}))})
const polylinePoints=computed(()=>chartPoints.value.map(point=>`${point.x},${point.y}`).join(' '))
const latestValue=computed(()=>{const values=metricValues.value;return values.length?values[values.length-1].value:'—'})
const delta=computed(()=>{const values=metricValues.value;if(values.length<2)return 0;return values[values.length-1].value-values[values.length-2].value})
const deltaText=computed(()=>`${delta.value>0?'+':''}${Number(delta.value.toFixed(3))} ${activeMetricInfo.value.unit}`.trim())
const deltaClass=computed(()=>delta.value>0?'delta-up':delta.value<0?'delta-down':'')
const firstTrendDate=computed(()=>metricValues.value.length?new Date(metricValues.value[0].observedAt).toLocaleDateString():'')
const lastTrendDate=computed(()=>{const values=metricValues.value;return values.length?new Date(values[values.length-1].observedAt).toLocaleDateString():''})
function targetDescription(target:TargetItem){const parts:string[]=[];if(target.temperatureMin!=null||target.temperatureMax!=null)parts.push(`水温 ${target.temperatureMin??'—'}–${target.temperatureMax??'—'} °C`);if(target.phMin!=null||target.phMax!=null)parts.push(`pH ${target.phMin??'—'}–${target.phMax??'—'}`);if(target.dissolvedOxygenMin!=null)parts.push(`溶氧 ≥ ${target.dissolvedOxygenMin}`);if(target.ammoniaMax!=null)parts.push(`氨氮 ≤ ${target.ammoniaMax}`);if(target.nitriteMax!=null)parts.push(`亚硝酸盐 ≤ ${target.nitriteMax}`);return parts.join(' · ')}
const activeTarget=computed(()=>targets.value.find(target=>target.pondName===selectedPond.value))
const activeTargetDescription=computed(()=>activeTarget.value?targetDescription(activeTarget.value):'')
function outOfRange(item:RecordItem,key:MetricKey){const target=targets.value.find(candidate=>candidate.pondName===item.pondName),value=item[key];if(!target||typeof value!=='number')return false;if(key==='temperature')return(target.temperatureMin!=null&&value<target.temperatureMin)||(target.temperatureMax!=null&&value>target.temperatureMax);if(key==='ph')return(target.phMin!=null&&value<target.phMin)||(target.phMax!=null&&value>target.phMax);if(key==='dissolvedOxygen')return target.dissolvedOxygenMin!=null&&value<target.dissolvedOxygenMin;if(key==='ammonia')return target.ammoniaMax!=null&&value>target.ammoniaMax;return target.nitriteMax!=null&&value>target.nitriteMax}
function deviationLabels(item:RecordItem){return metrics.filter(metric=>outOfRange(item,metric.key)).map(metric=>metric.label)}
function createRetestTask(item:RecordItem){const deviations=deviationLabels(item);const readings=metrics.filter(metric=>typeof item[metric.key]==='number').map(metric=>`${metric.label} ${item[metric.key]} ${metric.unit}`.trim()).join('，');router.push({path:'/fish/tasks',query:{source:'water-quality',title:`复测${item.pondName}水质`,pond:item.pondName,category:'WATER_TEST',notes:`来源：${formatDate(item.observedAt)} 的水质记录。偏离个人范围：${deviations.join('、')}。原始读数：${readings}。`}})}
function latestSummary(item:RecordItem){const values=metrics.filter(metric=>typeof item[metric.key]==='number').map(metric=>`${metric.label} ${item[metric.key]}${metric.unit?` ${metric.unit}`:''}`);return values.slice(0,3).join(' · ')+(values.length>3?' · …':'')}
async function selectPond(pondName:string){selectedPond.value=pondName;await loadTrend();document.querySelector('.trend-card')?.scrollIntoView({behavior:'smooth',block:'start'})}
function startDiagnosis(pond:PondOverview){router.push({path:'/fish/diagnose',query:{waterRecord:String(pond.latest.id)}})}
function scheduleWaterTest(pond:PondOverview){router.push({path:'/fish/tasks',query:{source:'water-quality',title:`检测${pond.pondName}水质`,pond:pond.pondName,category:'WATER_TEST',notes:`${pond.pondName}上次测量于 ${formatDate(pond.latest.observedAt)}，已有 ${pond.ageDays} 天未更新，请重新检测并记录关键指标。`}})}
async function initialize(){const rawPond=Array.isArray(route.query.pond)?route.query.pond[0]:route.query.pond;const requestedPond=typeof rawPond==='string'?rawPond.trim().slice(0,64):'';const rawTaskId=Array.isArray(route.query.taskId)?route.query.taskId[0]:route.query.taskId;const parsedTaskId=typeof rawTaskId==='string'?Number(rawTaskId):NaN;if(Number.isSafeInteger(parsedTaskId)&&parsedTaskId>0){linkedTaskId.value=parsedTaskId;linkedTaskTitle.value=queryText(route.query.taskTitle,100);if(requestedPond)form.value.pondName=requestedPond}if(requestedPond)selectedPond.value=requestedPond;await Promise.all([load(),loadPonds(),loadTargets(),loadOverview()]);if(linkedTaskId.value){await nextTick();formSection.value?.scrollIntoView({behavior:'smooth',block:'start'})}else if(requestedPond&&selectedPond.value===requestedPond){await nextTick();document.querySelector('.trend-card')?.scrollIntoView({behavior:'smooth',block:'start'})}}
function queryText(value:unknown,max:number){const text=Array.isArray(value)?value[0]:value;return typeof text==='string'?text.trim().slice(0,max):''}
onMounted(initialize)
</script>

